pub fn slice(addr: u32, size: usize) -> &'static mut [u8] {
    let result: &'static mut [u8] =
        unsafe { core::slice::from_raw_parts_mut(addr as *mut u8, size) };

    result
}

pub fn create_digest_buf(addr: u32) -> &'static mut PkaEccDigest {
    let ptr: *const PkaEccDigest = addr as *mut PkaEccDigest;
    let reg: &mut PkaEccDigest = unsafe { core::mem::transmute(ptr) };

    reg
}

