fn do_end_ecc_gen_key<I: InterruptControllerTrait>(
    pka: &mut Pka<I>,
    tag: u16,
    op: PkaEccCmd,
) -> PkaEccKeyPair {
    for _ in 0..TIMEOUT_COUNTER {
        let completion = pka.end_ecc_gen_key(tag, op);
        if let Ok(result) = completion {
            return result;
        }
    }

    panic!();
}

fn do_end_ecc_sign_zc<I: InterruptControllerTrait>(pka: &mut Pka<I>, tag: u16) {
    for _ in 0..TIMEOUT_COUNTER {
        match pka.end_ecc_sign_zc(tag) {
            Ok(()) => return,
            Err(_) => panic!(),
        }
    }

    panic!();
}

