pub fn reverse_copy(src: &[u8], dst: &mut [u8]) {
    for (item1, item2) in src.iter().rev().zip(dst.iter_mut()) {
        *item2 = *item1;
    }
}

fn extract_keys(
    curve: PkaEccCurve,
    key_pair: PkaEccKeyPair,
    pubkey: &mut PkaEccPublicKey,
    privkey: &mut PkaEccPrivateKey,
) {
    privkey.curve = curve;
    privkey.k_mut().copy_from_slice(key_pair.priv_key.k());

    pubkey.curve = curve;
    pubkey.x_mut().copy_from_slice(key_pair.pub_key.x());
    pubkey.y_mut().copy_from_slice(key_pair.pub_key.y());
}

fn init_pka(pka_instance: PkaInstanceId) -> Pka<InterruptController> {
    let pka_cmd_buf = create_pka_cmd_buf(PKA_CMD_BUF);
    let intc = InterruptController::default();

    let status =
        Pka::<InterruptController>::global_init(slice(CONST_BUF, PKA_CONST_MAX_SIZE_BYTES));
    assert!(status.is_ok());

    Pka::new(
        pka_instance,
        pka_cmd_buf,
        slice(RESULT_BUF_512, PKA_RESULT_MAX_SIZE_BYTES),
        slice(INPUT_BUF, PKA_INPUT_MAX_SIZE_BYTES),
        slice(CONST_BUF, PKA_CONST_MAX_SIZE_BYTES),
        intc,
        slice(SELF_TEST_BUF, PKA_SELF_TEST_MAX_SIZE_BYTES),
    )
}

fn create_buffers() -> (
    &'static mut PkaEccDigest,
    &'static mut PkaEccPrivateKey,
    &'static mut PkaEccPublicKey,
    &'static mut PkaEccSignature,
) {
    let digest = create_digest_buf(DIGEST_BUF);
    let privkey = create_privkey_buf(PRIVKEY_BUF);
    let pubkey = create_pubkey_buf(PUBKEY_BUF);
    let signature = create_signature_buf(SIGNATURE_BUF);
    (digest, privkey, pubkey, signature)
}

fn test_ecc_gen_key(curve: PkaEccCurve) {
    let (digest, privkey, pubkey, signature) = create_buffers();

    digest.digest_be = [0; PkaEccCurve::MAX_LEN];
    digest.len = curve.len();

    enable_rng();

    for pka_instance in PkaInstanceId::iter() {
        let mut pka = init_pka(pka_instance);
        let cmd = pka.begin_ecc_gen_key(PKA_TEST_TAG, curve).unwrap();

        let key_pair = do_end_ecc_gen_key(&mut pka, PKA_TEST_TAG, cmd);
        extract_keys(curve, key_pair, pubkey, privkey);

        let _ = pka
            .begin_ecc_sign_zc(
                PKA_TEST_TAG,
                curve,
                privkey.k(),
                &digest.digest_be[..].into(),
                &signature.r[..].into(),
            )
            .unwrap();

        do_end_ecc_sign_zc(&mut pka, PKA_TEST_TAG);

        let status_verify = pka.begin_ecc_verify_zc(
            PKA_TEST_TAG,
            curve,
            &pubkey.data[..].into(),
            &digest.digest_be[..].into(),
            &signature.r[..].into(),
        );
        assert!(status_verify.is_ok());

        assert_eq!(do_end_ecc_verify_zc(&mut pka, PKA_TEST_TAG), true);
    }
}

fn test_pka_ecc_key_generate_256_polling() {
    test_ecc_gen_key(PkaEccCurve::Ecc256);
}

fn test_pka_ecc_256_pka_busy_polling() {
    test_busy_polling(PkaEccCurve::Ecc256);
}

fn test_busy_polling(curve: PkaEccCurve) {
    let (digest, privkey, _pubkey, signature) = create_buffers();

    let tag: u16 = 123;

    enable_rng();

    for pka_instance in PkaInstanceId::iter() {
        let pka = init_pka(pka_instance);
        let _status_generate = pka.begin_ecc_gen_key(tag, curve);
        let status_sign = pka.begin_ecc_sign_zc(
            tag,
            curve,
            privkey.k(),
            &digest.digest_be[..].into(),
            &signature.r[..].into(),
        );
        assert!(status_sign.is_err());
    }
}

