fn test_sign_helper<I: InterruptControllerTrait>(
    mut pka: Pka<I>,
    curve: PkaEccCurve,
    digest: &mut PkaEccDigest,
    privkey: &mut PkaEccPrivateKey,
    signature: &mut PkaEccSignature,
    pubkey: &mut PkaEccPublicKey,
    base_point: &[u8],
) {
    privkey.curve = curve;
    signature.curve = curve;
    pubkey.curve = curve;

    let _ = pka
        .begin_ecc_sign_zc(
            PKA_TEST_TAG,
            curve,
            privkey.k(),
            &digest.digest_be[..].into(),
            &signature.r[..].into(),
        )
        .unwrap();

    let _ = do_end_ecc_sign_zc(&mut pka, PKA_TEST_TAG);

    let status_mont = pka.begin_montgomery_constant_calculation(PKA_TEST_TAG, curve);
    assert!(status_mont.is_ok());
    do_end_montgomery_constant_calc(&mut pka, PKA_TEST_TAG);

    let pub_key_range = IoMemRange::from(&pubkey.data[..]);
    let pubkey_cmd = pka
        .begin_ecc_gen_pub_key_zc(PKA_TEST_TAG, curve, privkey.k(), &pub_key_range)
        .unwrap();
    let _result = do_end_ecc_gen_pub_key(&mut pka, PKA_TEST_TAG, pubkey_cmd);
    pubkey.curve = pubkey_cmd.curve;

    let status_mont = pka.begin_montgomery_constant_calculation(PKA_TEST_TAG, curve);
    assert!(status_mont.is_ok());
    do_end_montgomery_constant_calc(&mut pka, PKA_TEST_TAG);

    let ecdh_op = pka
        .begin_ecdh_compute_zc(PKA_TEST_TAG, curve, privkey.k(), &base_point[..].into())
        .unwrap();
    let secret_val = do_end_ecdh_compute(&mut pka, PKA_TEST_TAG, ecdh_op);
    assert_eq!(secret_val.secret(), pubkey.x());

    pka.begin_ecc_verify_zc(
        PKA_TEST_TAG,
        curve,
        &pubkey.data[..].into(),
        &digest.digest_be[..].into(),
        &signature.r[..].into(),
    )
    .unwrap();
    assert_eq!(do_end_ecc_verify_zc(&mut pka, PKA_TEST_TAG), true);
}

