fn test_bad_sign_helper<I: InterruptControllerTrait>(
    mut pka: Pka<I>,
    curve: PkaEccCurve,
    digest: &mut PkaEccDigest,
    privkey: &mut PkaEccPrivateKey,
    signature: &mut PkaEccSignature,
    pubkey: &mut PkaEccPublicKey,
) {
    privkey.curve = curve;

    let _ = pka
        .begin_ecc_sign_zc(
            PKA_TEST_TAG,
            curve,
            privkey.k(),
            &digest.digest_be[..].into(),
            &signature.r[..].into(),
        )
        .unwrap();
    do_end_ecc_sign_zc(&mut pka, PKA_TEST_TAG);
    // Mutate the signature.
    signature.r[7] = 0xff;
    signature.r[8] = 0xff;

    let mont_status = pka.begin_montgomery_constant_calculation(PKA_TEST_TAG, curve);
    assert!(mont_status.is_ok());
    do_end_montgomery_constant_calc(&mut pka, PKA_TEST_TAG);

    let pub_key_range = IoMemRange::from(&pubkey.data[..]);
    let pubkey_cmd = pka
        .begin_ecc_gen_pub_key_zc(PKA_TEST_TAG, curve, privkey.k(), &pub_key_range)
        .unwrap();
    let _result = do_end_ecc_gen_pub_key(&mut pka, PKA_TEST_TAG, pubkey_cmd);
    pubkey.curve = pubkey_cmd.curve;

    let status_verify = pka.begin_ecc_verify_zc(
        PKA_TEST_TAG,
        curve,
        &pubkey.data[..].into(),
        &digest.digest_be[..].into(),
        &signature.r[..].into(),
    );
    assert!(status_verify.is_ok());

    assert_eq!(do_end_ecc_verify_zc(&mut pka, PKA_TEST_TAG), false);
}

