fn wait_and_check_interrupt_status(pka_instance: PkaInstanceId, intc: &InterruptController) {
    let error_interrupt = get_pka_error_interrupt(pka_instance);
    assert!(error_interrupt.is_some());
    let done_interrupt = get_pka_done_interrupt(pka_instance);
    assert!(done_interrupt.is_some());

    loop {
        if intc.pending(done_interrupt.unwrap()) {
            intc.clear(done_interrupt.unwrap());
            break;
        }
    }

    assert_eq!(intc.pending(error_interrupt.unwrap()), false);
}

fn test_pka_ecc_key_generate_256_interrupt() {
    test_ecc_gen_key_interrupt(PkaEccCurve::Ecc256);
}

fn test_ecc_gen_key_interrupt(curve: PkaEccCurve) {
    let (digest, privkey, pubkey, signature) = create_buffers();
    (*digest).digest_be = [0u8; PkaEccCurve::MAX_LEN];

    let intc = InterruptController::default();

    enable_rng();

    for pka_instance in PkaInstanceId::iter() {
        let mut pka = init_pka(pka_instance);

        let done_interrupt = get_pka_done_interrupt(pka_instance);
        assert!(done_interrupt.is_some());

        intc.clear(done_interrupt.unwrap());
        let gen_key_cmd = pka.begin_ecc_gen_key(PKA_TEST_TAG, curve).unwrap();
        wait_and_check_interrupt_status(pka_instance, &intc);
        let key_pair = do_end_ecc_gen_key(&mut pka, PKA_TEST_TAG, gen_key_cmd);
        extract_keys(curve, key_pair, pubkey, privkey);

        intc.clear(done_interrupt.unwrap());
        let _ = pka
            .begin_ecc_sign_zc(
                PKA_TEST_TAG,
                curve,
                privkey.k(),
                &digest.digest_be[..].into(),
                &signature.r[..].into(),
            )
            .unwrap();
        wait_and_check_interrupt_status(pka_instance, &intc);
        do_end_ecc_sign_zc(&mut pka, PKA_TEST_TAG);

        intc.clear(done_interrupt.unwrap());
        let result = pka.begin_ecc_verify_zc(
            PKA_TEST_TAG,
            curve,
            &pubkey.data[..].into(),
            &digest.digest_be[..].into(),
            &signature.r[..].into(),
        );
        assert!(result.is_ok());
        wait_and_check_interrupt_status(pka_instance, &intc);
        assert_eq!(do_end_ecc_verify_zc(&mut pka, PKA_TEST_TAG), true);
    }
}

